sections.body:
**The problem without modules:** you have EKS infra for prod and staging. You copy the `.tf` files and change a few values. Now you have two copies to maintain and they drift. A security fix in prod doesn't automatically go to staging.

**With modules:** define the EKS cluster once as a module. Call it twice with different variables.

```
infra/
  modules/
    eks-cluster/       # the module (define once)
      main.tf
      variables.tf
      outputs.tf
  environments/
    prod/
      main.tf          # calls the module
    staging/
      main.tf          # calls the same module
```

```hcl
# modules/eks-cluster/variables.tf
variable "cluster_name" {
  type        = string
  description = "EKS cluster name"
}

variable "kubernetes_version" {
  type    = string
  default = "1.35"
}

variable "node_instance_types" {
  type    = list(string)
  default = ["t3.medium"]
}

variable "min_nodes" {
  type    = number
  default = 2
}

variable "max_nodes" {
  type    = number
  default = 10
}

variable "tags" {
  type    = map(string)
  default = {}
}
```

```hcl
# modules/eks-cluster/main.tf
terraform {
  required_providers {
    aws = { source = "hashicorp/aws", version = "~> 5.0" }
  }
}

resource "aws_eks_cluster" "this" {
  name     = var.cluster_name
  version  = var.kubernetes_version
  role_arn = aws_iam_role.cluster.arn

  vpc_config {
    subnet_ids = var.subnet_ids
  }

  tags = merge(var.tags, {
    ManagedBy = "terraform"
  })
}

resource "aws_eks_node_group" "this" {
  cluster_name    = aws_eks_cluster.this.name
  node_group_name = "${var.cluster_name}-nodegroup"
  node_role_arn   = aws_iam_role.node.arn
  subnet_ids      = var.subnet_ids

  instance_types = var.node_instance_types

  scaling_config {
    desired_size = var.min_nodes
    min_size     = var.min_nodes
    max_size     = var.max_nodes
  }

  tags = var.tags
}

# modules/eks-cluster/outputs.tf
output "cluster_name" {
  value = aws_eks_cluster.this.name
}

output "cluster_endpoint" {
  value = aws_eks_cluster.this.endpoint
}

output "cluster_ca" {
  value     = aws_eks_cluster.this.certificate_authority[0].data
  sensitive = true
}

# environments/prod/main.tf — calling the module
module "eks_prod" {
  source = "../../modules/eks-cluster"

  cluster_name          = "eks-prod-mach-x7kq"
  kubernetes_version    = "1.35"
  node_instance_types   = ["m6a.2xlarge"]
  min_nodes             = 3
  max_nodes             = 10
  subnet_ids            = module.vpc.private_subnet_ids

  tags = {
    Environment = "prod"
    Team        = "platform"
  }
}

# environments/staging/main.tf
module "eks_staging" {
  source = "../../modules/eks-cluster"

  cluster_name        = "eks-staging"
  kubernetes_version  = "1.35"
  node_instance_types = ["t3.medium"]   # cheaper for staging
  min_nodes           = 2
  max_nodes           = 5
  subnet_ids          = module.vpc.private_subnet_ids

  tags = { Environment = "staging" }
}
```

**The problem with `count`:** if you use `count = 3` to create 3 subnets and then remove the middle one, Terraform destroys and recreates subnet[2] (renaming it) instead of just deleting subnet[1]. This causes unnecessary disruption.

**`for_each` uses keys, not indices**, so removing one element only affects that element.

```hcl
# BAD: count-based (index-sensitive)
resource "aws_subnet" "this" {
  count             = 3
  cidr_block        = "10.0.${count.index}.0/24"
  availability_zone = var.azs[count.index]
}
# Removing index 1 → Terraform destroys [1] and [2], recreates [2] as new [1]

# GOOD: for_each (key-stable)
locals {
  subnets = {
    "eu-central-1a" = "10.0.1.0/24"
    "eu-central-1b" = "10.0.2.0/24"
    "eu-central-1c" = "10.0.3.0/24"
  }
}

resource "aws_subnet" "this" {
  for_each          = local.subnets
  cidr_block        = each.value
  availability_zone = each.key
}
# Removing "eu-central-1b" → only destroys that one subnet

# for_each with a set of strings
resource "aws_security_group_rule" "ingress" {
  for_each    = toset(["80", "443", "8080"])
  type        = "ingress"
  from_port   = each.key
  to_port     = each.key
  protocol    = "tcp"
  cidr_blocks = ["0.0.0.0/0"]
  security_group_id = aws_security_group.main.id
}

# Reference for_each resources
output "subnet_ids" {
  value = [for s in aws_subnet.this : s.id]
}
```
